function testRiskyFileNames() {
  console.log(riskyFileNames(["index.html", "Garden.JPG", "plant spacing.html", "style.css"]))
}

function riskyFileNames(names) {
  const risky = []
  for (let i = 0; i < names.length; i++) {
    const name = names[i]
    const hasCapital = name !== name.toLowerCase()
    const hasSpace = name.split(" ").length > 1
    if (hasCapital || hasSpace) {
      risky.push(name)
    }
  }
  return risky
}
